-- Westeros travel system: ordered workbook data.
-- Run after event-log.sql, world-state-schema.sql, and opening-state-seed.sql.
-- Execute this complete file once, then continue with the next numbered file.

begin;

on conflict(import_id,sheet_name,row_number) do update set row_data=excluded.row_data;

on conflict(import_id,sheet_name,row_number) do update set row_data=excluded.row_data;

on conflict(import_id,sheet_name,row_number) do update set row_data=excluded.row_data;

on conflict(import_id,sheet_name,row_number) do update set row_data=excluded.row_data;

on conflict(import_id,sheet_name,row_number) do update set row_data=excluded.row_data;

on conflict(import_id,sheet_name,row_number) do update set row_data=excluded.row_data;

on conflict(import_id,sheet_name,row_number) do update set row_data=excluded.row_data;

select (select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'),seed.source_name,seed.source_url,seed.supports,seed.use_limitations,seed.source_row_number
from (values
  ('Map of Westeros — Distance Calculator', 'https://mapofwesteros.com/distances/', 'Map scale / route-distance estimates', 'Map calibrated around King''s Landing–Winterfell at roughly 1,500 mi; other distances are estimates, not official canon measurements.', 5),
  ('Map of Westeros — Regions', 'https://mapofwesteros.com/regions/', 'Regional geography', 'Region layout and geographic positioning used for route plausibility.', 6),
  ('Map of Westeros — Locations', 'https://mapofwesteros.com/locations/', 'Location geography', 'Playable-seat and location positioning for map-derived ranges.', 7),
  ('A Wiki of Ice and Fire — Kingsroad', 'https://awoiaf.westeros.org/index.php/Kingsroad', 'Kingsroad topology', 'Main north–south road; combine with the supplied world-bible and map calibration.', 8),
  ('A Wiki of Ice and Fire — River Road', 'https://awoiaf.westeros.org/index.php/River_road', 'River Road topology', 'Western route corridor; Golden Tooth pass remains a separate strategic chokepoint.', 9),
  ('A Wiki of Ice and Fire — High Road', 'https://awoiaf.westeros.org/index.php/High_road', 'High Road / Vale approach', 'High Road route into the Vale; Bloody Gate and final Eyrie ascent are distinct constraints.', 10),
  ('A Wiki of Ice and Fire — Roseroad', 'https://awoiaf.westeros.org/index.php/Roseroad', 'Roseroad topology', 'King''s Landing–Reach corridor toward Highgarden and Oldtown.', 11),
  ('A Wiki of Ice and Fire — Goldroad', 'https://awoiaf.westeros.org/index.php/Goldroad', 'Goldroad topology', 'King''s Landing–Westerlands corridor; not interchangeable with River Road.', 12),
  ('A Wiki of Ice and Fire — Ocean Road', 'https://awoiaf.westeros.org/index.php/Ocean_Road', 'Ocean Road topology', 'Lannisport / Westerlands coast toward the Reach.', 13),
  ('A Wiki of Ice and Fire — Boneway', 'https://awoiaf.westeros.org/index.php/Boneway', 'Boneway topology', 'Eastern mountain pass into Dorne; Yronwood controls the Dornish end.', 14),
  ('A Wiki of Ice and Fire — Prince''s Pass', 'https://awoiaf.westeros.org/index.php/Prince%27s_Pass', 'Prince''s Pass topology', 'Western mountain pass between the Reach/marches and Dorne.', 15),
  ('A Wiki of Ice and Fire — Duskendale', 'https://awoiaf.westeros.org/index.php/Duskendale', 'Crownlands coastal route context', 'Duskendale''s position on the route between King''s Landing and Maidenpool.', 16),
  ('A Wiki of Ice and Fire — The Twins', 'https://awoiaf.westeros.org/index.php/The_Twins', 'Green Fork crossing / chokepoint', 'The Twins bridge is an optional Green Fork crossing, not part of the standard Kingsroad itinerary.', 17),
  ('A Wiki of Ice and Fire — Moat Cailin', 'https://awoiaf.westeros.org/index.php/Moat_Cailin', 'Neck bottleneck', 'Strategic control of north–south access through the Neck.', 18),
  ('A Wiki of Ice and Fire — The Eyrie', 'https://awoiaf.westeros.org/index.php/The_Eyrie', 'Final Vale ascent', 'Mountain location and constrained access.', 19)
) as seed(source_name,source_url,supports,use_limitations,source_row_number)
join public.travel_workbook_rows raw on raw.import_id=(select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af') and raw.sheet_name='SOURCE REGISTER' and raw.row_number=seed.source_row_number
on conflict(import_id,source_name) do update set source_url=excluded.source_url,supports=excluded.supports,use_limitations=excluded.use_limitations,source_row_number=excluded.source_row_number;

select location.id,(select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'),seed.region_name,seed.location_type,seed.starting_house,seed.current_house,seed.priority_rank,seed.is_core10,seed.is_playable,seed.geography_note,seed.implementation_note,seed.source_row_number
from (values
  ('King''s Landing', 'The Crownlands', 'capital city', 'House Baratheon', 'House Baratheon', 1, TRUE, TRUE, 'The Crownlands (capital city): Road and sea hub: Kingsroad, Goldroad, Roseroad, Blackwater ferry and royal harbour.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 5),
  ('Winterfell', 'The North', 'castle', 'House Stark', 'House Stark', 2, TRUE, TRUE, 'The North (castle): Northern road hub on the Kingsroad; regional roads reach White Harbor and the eastern North.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 6),
  ('Casterly Rock', 'The Westerlands', 'castle', 'House Lannister', 'House Lannister', 3, TRUE, TRUE, 'The Westerlands (castle): Lannister seat above Lannisport; access to Goldroad, Ocean Road and River Road.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 7),
  ('Dragonstone', 'The Crownlands', 'island castle', 'House Baratheon of Dragonstone', 'House Baratheon of Dragonstone', 4, TRUE, TRUE, 'The Crownlands (island castle): Island fortress; all ordinary travel requires a vessel.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 8),
  ('Storm''s End', 'The Stormlands', 'coastal castle', 'House Baratheon', 'House Baratheon', 5, TRUE, TRUE, 'The Stormlands (coastal castle): Stormlands road hub; Kingsroad north and roads toward the Dornish Marches.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 9),
  ('The Eyrie', 'The Vale', 'mountain castle', 'House Arryn', 'House Arryn', 6, TRUE, TRUE, 'The Vale (mountain castle): Reached by High Road/Bloody Gate, Gates of the Moon and a separate final ascent.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 10),
  ('Riverrun', 'The Riverlands', 'castle', 'House Tully', 'House Tully', 7, TRUE, TRUE, 'The Riverlands (castle): At the Tumblestone/Red Fork confluence; River Road and Riverlands regional hub.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 11),
  ('Highgarden', 'The Reach', 'castle', 'House Tyrell', 'House Tyrell', 8, TRUE, TRUE, 'The Reach (castle): Reach road hub: Roseroad east, Ocean Road west, regional roads south, Roseroad toward Oldtown.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 12),
  ('Sunspear', 'Dorne', 'coastal city', 'House Nymeros Martell', 'House Nymeros Martell', 9, TRUE, TRUE, 'Dorne (coastal city): Eastern Dornish hub near Planky Town; inland roads run through eastern and central Dorne.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 13),
  ('Pyke', 'The Iron Islands', 'island castle', 'House Greyjoy', 'House Greyjoy', 10, TRUE, TRUE, 'The Iron Islands (island castle): Sea-stack castle; travel to mainland and other islands is by ship.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 14),
  ('Starfall', 'Dorne', 'castle', 'House Dayne', 'House Dayne', NULL, FALSE, TRUE, 'Dorne (castle): At the Torrentine mouth on Dorne’s far western coast; regional roads and a plausible coastal landing, but no quantified major harbour capacity.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 15),
  ('Yronwood', 'Dorne', 'castle', 'House Yronwood', 'House Yronwood', NULL, FALSE, TRUE, 'Dorne (castle): Controls the Dornish end of the Boneway and the eastern mountain approach.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 16),
  ('Driftmark', 'The Crownlands', 'island seat', 'House Velaryon', 'House Velaryon', NULL, FALSE, TRUE, 'The Crownlands (island seat): Island seat with the port of Hull; all mainland travel requires a vessel.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 17),
  ('Duskendale', 'The Crownlands', 'port town', 'House Rykker', 'House Rykker', NULL, FALSE, TRUE, 'The Crownlands (port town): Blackwater Bay port; the King’s Landing–Maidenpool coastal road passes through it.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 18),
  ('Ten Towers', 'The Iron Islands', 'castle', 'House Harlaw', 'House Harlaw', NULL, FALSE, TRUE, 'The Iron Islands (castle): House Harlaw seat on Harlaw; inter-island and mainland movement requires ships.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 19),
  ('Moat Cailin', 'The North', 'fortress', NULL, NULL, NULL, FALSE, TRUE, 'The North (fortress): Commands the Kingsroad causeway through the Neck; ordinary army movement is bottlenecked here.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 20),
  ('The Dreadfort', 'The North', 'castle', 'House Bolton', 'House Bolton', NULL, FALSE, TRUE, 'The North (castle): Eastern North seat reached by regional roads, not directly on the Kingsroad.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 21),
  ('White Harbor', 'The North', 'port city', 'House Manderly', 'House Manderly', NULL, FALSE, TRUE, 'The North (port city): Principal northern port at the White Knife; connected by road to Winterfell and by sea to eastern ports.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 22),
  ('Horn Hill', 'The Reach', 'castle', 'House Tarly', 'House Tarly', NULL, FALSE, TRUE, 'The Reach (castle): Southern Reach seat on regional roads between Highgarden and Oldtown, toward the marcher country.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 23),
  ('Oldtown', 'The Reach', 'city port', 'House Hightower', 'House Hightower', NULL, FALSE, TRUE, 'The Reach (city port): Major southern port and Roseroad terminus; sea access to the Arbor and southern coast.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 24),
  ('The Arbor', 'The Reach', 'island port', 'House Redwyne', 'House Redwyne', NULL, FALSE, TRUE, 'The Reach (island port): Island port across the Redwyne Straits; all mainland travel requires ships.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 25),
  ('Harrenhal', 'The Riverlands', 'castle', 'House Whent', 'House Whent', NULL, FALSE, TRUE, 'The Riverlands (castle): Ruined castle beside the God’s Eye near the Kingsroad/Riverlands corridor.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 26),
  ('Maidenpool', 'The Riverlands', 'port town', 'House Mooton', 'House Mooton', NULL, FALSE, TRUE, 'The Riverlands (port town): Walled port on the Bay of Crabs; reached from King’s Landing through Duskendale.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 27),
  ('Seagard', 'The Riverlands', 'coastal castle', 'House Mallister', 'House Mallister', NULL, FALSE, TRUE, 'The Riverlands (coastal castle): Western Riverlands coast on Ironman’s Bay; land road to Riverrun and sea lane to the Iron Islands.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 28),
  ('The Twins', 'The Riverlands', 'castle crossing', 'House Frey', 'House Frey', NULL, FALSE, TRUE, 'The Riverlands (castle crossing): Fortified bridge over the Green Fork; crossing requires Frey control/permission or force.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 29),
  ('Griffin''s Roost', 'The Stormlands', 'castle', 'House Connington', 'House Connington', NULL, FALSE, TRUE, 'The Stormlands (castle): Coastal Cape Wrath castle reached by a single causeway; regional road to Storm’s End.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 30),
  ('Gulltown', 'The Vale', 'port city', 'House Grafton', 'House Grafton', NULL, FALSE, TRUE, 'The Vale (port city): Vale’s principal port and sea arrival hub; inland roads lead toward the Vale.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 31),
  ('Runestone', 'The Vale', 'castle', 'House Royce', 'House Royce', NULL, FALSE, TRUE, 'The Vale (castle): Eastern Vale coastal seat; local road connections to Gulltown and the Eyrie.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 32),
  ('Lannisport', 'The Westerlands', 'port city', 'House Lannister', 'House Lannister', NULL, FALSE, TRUE, 'The Westerlands (port city): Major harbour below Casterly Rock; sea access and local road to the Rock.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 33),
  ('The Golden Tooth', 'The Westerlands', 'fortress', 'House Lefford', 'House Lefford', NULL, FALSE, TRUE, 'The Westerlands (fortress): Commands the River Road pass from the Westerlands into the Riverlands.', 'Lookup foreign keys by exact name; do not hard-code IDs.', 34)
) as seed(name,region_name,location_type,starting_house,current_house,priority_rank,is_core10,is_playable,geography_note,implementation_note,source_row_number)
join public.playable_locations location on location.name=seed.name
on conflict(location_id) do update set import_id=excluded.import_id,region_name=excluded.region_name,location_type=excluded.location_type,normalized_starting_house=excluded.normalized_starting_house,normalized_house=excluded.normalized_house,priority_rank=excluded.priority_rank,is_core10=excluded.is_core10,is_playable=excluded.is_playable,geography_note=excluded.geography_note,implementation_note=excluded.implementation_note,source_row_number=excluded.source_row_number;

do $$ begin if (select count(*) from public.travel_location_reference where import_id=(select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'))<>30 then raise exception 'Travel workbook location import did not link all 30 names. Check playable_locations.name exact matches.'; end if; end $$;

update public.playable_locations location set travel_priority_rank=ref.priority_rank,is_travel_core=ref.is_core10,travel_geography_note=ref.geography_note,world_region_id=coalesce(location.world_region_id,region.id) from public.travel_location_reference ref left join public.world_regions region on region.name=ref.region_name where location.id=ref.location_id and ref.import_id=(select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af');

select (select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af'),seed.corridor_name,seed.network_class,seed.edge_modes,seed.edge_count,seed.playable_locations_touched,seed.edge_keys,seed.waypoint_catalogue,seed.description,seed.confidence_level,seed.source_url,(select id from public.travel_sources where import_id=(select id from public.travel_workbook_imports where import_key='westeros-travel-atlas-470d49648de6b2af') and source_url=seed.source_url order by id limit 1),seed.source_row_number
from (values
  ('Blackwater Bay', 'Sea', ARRAY['sea']::text[], 1, ARRAY['Driftmark', 'King''s Landing']::text[], ARRAY['E46']::text[], ARRAY['Driftmark/Hull', 'King’s Landing harbour']::text[], 'Sea lane across Blackwater Bay; exact sailing mileage is an inferred implementation range.', 'low', 'https://mapofwesteros.com/locations/', 5),
