  ('Crownlands coastal road', 'Road', ARRAY['road']::text[], 3, ARRAY['Duskendale', 'King''s Landing', 'Maidenpool']::text[], ARRAY['E16', 'E17', 'E18']::text[], ARRAY['Bay of Crabs', 'Coastal road', 'Duskendale', 'North shore of Blackwater Bay']::text[], 'King''s Landing to Maidenpool coast road via Duskendale on the north shore of Blackwater Bay.', 'low', 'https://awoiaf.westeros.org/index.php/Duskendale', 9),
  ('Dornish regional road', 'Regional road', ARRAY['road']::text[], 2, ARRAY['Starfall', 'Sunspear', 'Yronwood']::text[], ARRAY['E37', 'E38']::text[], ARRAY['Dornish interior', 'Eastern Dorne', 'Torrentine valley']::text[], 'Inferred inland network connecting Starfall, Sunspear and Yronwood across Dorne; exact route geometry is not canonically measured.', 'low', 'https://mapofwesteros.com/regions/', 10),
