  ('Eastern coast sea lane', 'Inferred regional route / sea lane', ARRAY['sea']::text[], 1, ARRAY['Gulltown', 'White Harbor']::text[], ARRAY['E23']::text[], ARRAY['Bite', 'Gulltown harbour', 'Narrow Sea']::text[], 'Inferred/game route label used to connect playable nodes in the route graph. Treat exact alignment and mileage as an implementation estimate unless supported by a named source.', 'low', 'https://mapofwesteros.com/locations/', 13),
  ('Goldroad', 'Road', ARRAY['road']::text[], 1, ARRAY['Casterly Rock', 'King''s Landing']::text[], ARRAY['E25']::text[], ARRAY['Lion Gate', 'river crossings', 'western roads']::text[], 'Western trunk from King''s Landing across the western road corridor to the Westerlands and Casterly Rock/Lannisport. Do not conflate it with the River Road through Golden Tooth.', 'low', 'https://awoiaf.westeros.org/index.php/Goldroad', 14),
