  ('Ironman’s Bay', 'Inferred regional route / sea lane', ARRAY['sea']::text[], 2, ARRAY['Pyke', 'Seagard', 'Ten Towers']::text[], ARRAY['E49', 'E50']::text[], ARRAY['Harlaw', 'Ironman’s Bay', 'Pyke', 'Seagard', 'Seagard harbour']::text[], 'Inferred/game route label used to connect playable nodes in the route graph. Treat exact alignment and mileage as an implementation estimate unless supported by a named source.', 'low', 'https://mapofwesteros.com/locations/', 16),
